class CycleError(Exception):
    pass


def order(deps):
    seen, out = set(), []

    def visit(node):
        if node in seen:
            return
        seen.add(node)
        for dep in deps.get(node, []):
            visit(dep)
        out.append(node)

    for node in deps:
        visit(node)
    return out

import unittest
from mod import order
class T(unittest.TestCase):
    def test_chain(self):
        self.assertEqual(order({'b': ['a'], 'c': ['b']}), ['a', 'b', 'c'])
    def test_single(self):
        self.assertEqual(order({'a': []}), ['a'])

if __name__ == '__main__':
    unittest.main()
